import{_ as t,H as i,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"04 | 能力构建（上）：如何从做技术转变到做技术决策？","description":"","frontmatter":{},"headers":[{"level":2,"title":"体系搭建能力：从遵守规则到建立规则","slug":"体系搭建能力-从遵守规则到建立规则","link":"#体系搭建能力-从遵守规则到建立规则","children":[]},{"level":2,"title":"技术实力：从做技术到做技术决策","slug":"技术实力-从做技术到做技术决策","link":"#技术实力-从做技术到做技术决策","children":[{"level":3,"title":"初做管理的你应该怎么做呢？","slug":"初做管理的你应该怎么做呢","link":"#初做管理的你应该怎么做呢","children":[]},{"level":3,"title":"技术决策的三个门槛","slug":"技术决策的三个门槛","link":"#技术决策的三个门槛","children":[]}]},{"level":2,"title":"文化构建能力：让梦想变成理想","slug":"文化构建能力-让梦想变成理想","link":"#文化构建能力-让梦想变成理想","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"技术领导力实战笔记2022/04｜能力构建（上）：如何从做技术转变到做技术决策？.md","filePath":"技术领导力实战笔记2022/04｜能力构建（上）：如何从做技术转变到做技术决策？.md","lastUpdated":1795558086000}'),n={name:"技术领导力实战笔记2022/04｜能力构建（上）：如何从做技术转变到做技术决策？.md"};function s(p,e,E,r,o,h){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_04-能力构建-上-如何从做技术转变到做技术决策" tabindex="-1">04 | 能力构建（上）：如何从做技术转变到做技术决策？ <a class="header-anchor" href="#_04-能力构建-上-如何从做技术转变到做技术决策" aria-label="Permalink to &quot;04 | 能力构建（上）：如何从做技术转变到做技术决策？&quot;">​</a></h1><p>你好，我是郭炜，之前担任易观数据 CTO，目前在创业。今天我想和你聊一聊技术管理者的能力模型，以及如何提升的问题。</p><p>每个技术领导者，都是从做技术（管自己）到带领小组（管 10 个人）再到负责整个部门（管50～100 人） ，最后到统领公司技术人员（管 100～1000 人）逐步成长起来的。在成长的过程中要跨越很多道管理门槛，才能最终成长为一个能够统领公司技术人员的领导者。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/04/1.png" alt=""></a></p><p>上一季的分享中我给出了技术管理者的能力模型，也提到了不同技术管理岗位应该具备的能力以及侧重点，能力模型中的 5 项能力分别是领导力、技术实力、体系搭建能力、人员管理能力、文化构建能力。这些能力可以帮助我们跨越一个又一个管理门槛，成长为一个优秀的管理者。所以今天我们就来聊一聊，作为技术管理者，我们应该怎样提升这几项能力。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/04/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/04/2.png" alt=""></a></p><ul><li>技术管理核心能力-技术总监能力模型</li></ul><h2 id="体系搭建能力-从遵守规则到建立规则" tabindex="-1">体系搭建能力：从遵守规则到建立规则 <a class="header-anchor" href="#体系搭建能力-从遵守规则到建立规则" aria-label="Permalink to &quot;体系搭建能力：从遵守规则到建立规则&quot;">​</a></h2><p>你可能觉得从技术到技术管理，难道不是技术实力最容易吗？其实不是，技术管理者的技术实力，并不是做技术的实力，而是做技术决策的能力，它是一种软能力，相对于通过学习和培训就可以提高的“体系搭建能力”要复杂一些。</p><ul><li>体系搭建能力：从项目管理、架构管理、到人员管理、体系管理，什么时间用什么样的管理方法，控制好质量、进度、节奏、人员是一个管理人员能力的体现。——《你的能力模型决定你的职位》</li></ul><p>对于技术管理来说，体系搭建能力指的是构建“工程化”体系的能力。这对于经历过大厂或者大型软件开发公司训练的技术管理者更容易学习一些。大部分初级技术管理者，过去都是一个流程当中的螺丝钉，只懂得去遵守规则，完成自己负责的部分，但机器应该怎么运作，他们其实并不了解。</p><p>好在现在市面上，大多数讲技术管理培训的，都是在讲这部分能力，这部分能力是可以通过培训、实践快速提高的。所以如果你过去这方面经验不足，参加 1-2 个线下体系化培训，就可以快速掌握和提高这方面的技能，因此这是技术领导力模型当中最容易提高的一个象限。</p><h2 id="技术实力-从做技术到做技术决策" tabindex="-1">技术实力：从做技术到做技术决策 <a class="header-anchor" href="#技术实力-从做技术到做技术决策" aria-label="Permalink to &quot;技术实力：从做技术到做技术决策&quot;">​</a></h2><p>说到技术决策，大多数有技术背景的人都很自信，过去自己做了很多架构选型，不就是给领导汇报一下，让领导听明白，点个头吗？其实，当你真正做技术一把手的时候，反而不是那么简单。技术人转型为技术管理者时，最容易犯的错误就是无限制地追求技术发展的前瞻性。如果不审时度势只追新求异，很可能会导致公司业务无法达到预期目标，严重的话还会因为技术镀金导致公司整体失败。</p><p>我身边就曾经发生过这样的事情，前几年 Vue 3.0 横空出世，很多前端爱好者都觉得 Vue 3.0很不错，于是朋友公司的前端架构负责人向他们的 CTO 强烈推荐公司整体架构升级到 Vue3.0。朋友公司的 CTO 本身也是技术爱好者，看了很多 Vue 3.0 的特性后觉得的确非常好，再加上前端开发人员力荐，并承诺 3 个月内可以升级完成，于是他们决定把公司即将发布的新版本 3.0 全面升级到 Vue 3.0。</p><p>但他们进入开发状态后，却发现 Vue 3.0 版本太新，很多可以复用的组件都没有，必须重新开发，重新造轮子。同时，因为技术比较新，所有人都需要重新学习，市场上也招聘不到熟悉Vue 3.0 的人，因此耽误了产品发布，加钱加资源都搞不定。原定 3 个月要发布的新版本，一下做了 9 个月，公司现金流差点断掉。所以，技术人才变成管理人才的时候，第一要素考虑的永远不是技术，而是业务目标。团队适合用小米加步枪打游击战拿下战略高地的时候，你非让团队用飞机大炮做军团战反而会延误战机。</p><p>和技术人追求的不同，优秀的技术管理者需要考虑公司现有人员、团队磨合情况、公司投入情况几个维度，选择当前最适合的技术，而不是最新的技术。所以一个技术管理者，往往会站在架构师的对立面，重新剖析现有公司的整体情况，最终拍板技术选型。看上去虽然是一个简简单单的技术选型，但其实背后往往是团队成员的更换、技术生产力的变化、产品里程碑的延期等等后续不可控的结果。</p><p>管理者会从多重维度考量，做出更合适的选择。比如架构师觉得目前的技术框架很好，团队也做出了一些成绩，但管理者要升级框架，架构师表示不理解。这是因为双方的角度不同，没有在技术一把手的位置上，你看到的信息，都是局部信息。从整体上看，如果技术框架不升级、不随着实际情况调整，你的开发效率会慢慢降低，逐步落后于行业，所以选择什么样的技术，看上去是一个技术问题，其实它是一个管理问题。</p><h3 id="初做管理的你应该怎么做呢" tabindex="-1">初做管理的你应该怎么做呢？ <a class="header-anchor" href="#初做管理的你应该怎么做呢" aria-label="Permalink to &quot;初做管理的你应该怎么做呢？&quot;">​</a></h3><p>首先，当选型一个新技术，进行技术更迭的时候，你要做充分的调研、做好业务部门的沟通、团队的安排、风险的控制；其次，你要动用你的管理源力——勇气，世界上没有万全的准备，一定都会有所疏漏，但是，有经验的管理者能够及时止损，让问题在可控范围内。</p><p>比如之前我做 CTO 的时候，引入了当时最新的大数据混合云技术，利用公有云进行弹性数据接收的同时利用私有云计算大数据平台，达到大数据接收 + 大数据计算的最佳 ROI。当时业内还没有人这么做，但公司预算有限，不这么做可能会因为数据接收资源不够引发更大的问题。所以在那时候我拍板，吃了最新技术的螃蟹。</p><p>当然，在后期云厂商支持混合云之前，我们自建的光缆被挖断了一次，我被 CEO 骂了一顿。不过，没有这套吃螃蟹的架构，那时候的预算根本无法撑过双十一等一些数据暴增的场景，最终经过验证，还是利大于弊的。</p><p>世界上留给技术管理者的永远都是在资源有限的情况下，做出“两害相权取其轻”的选择，而不是一个普通技术人看性能测试报表，选那个表现最好的技术。作为一个技术管理者，问题可能会出在哪儿，最终你是否承担得起，你一定要做到心里有数。</p><h3 id="技术决策的三个门槛" tabindex="-1">技术决策的三个门槛 <a class="header-anchor" href="#技术决策的三个门槛" aria-label="Permalink to &quot;技术决策的三个门槛&quot;">​</a></h3><p>如果你刚刚转换角色，成为技术管理者，可能没办法一下子做到心中有数。你需要不断地学习，涉猎更多知识，提升自己的技术实力，从“无知”到“有知”，同时在这一过程中，你的心态也会发生很大变化。</p><p>总的来说，想要做好技术决策的你要迈过 3 个门槛：“无知而无畏”“有知而有畏”“有知而无畏”。</p><ol><li><p>“无知而无畏”就和大多数技术人员一样，追新求异，什么潮流就用什么，不对结果负责，最终升级失败给公司带来巨大损失的时候就傻眼了。</p></li><li><p>“有知而有畏”，发现原来做技术决策，用新技术风险这么大，心存敬畏，很多地方不敢放开手脚，这种情况比前面因为无知给公司造成巨大的损失要好很多，至少不会影响公司当前业务，但长期来讲不利于公司发展。</p></li><li><p>最后，对于业务影响、技术影响、团队影响稔熟于心，对于风险做到心中有数，还敢于拍板接受新的技术架构，做出卓越的技术决策，就达到了优秀的技术管理者“有知而无畏”的境界。</p></li></ol><p>跨越过这三道门槛，也就做到了心中有数，自己的硬实力也提升上来了。经过深思熟虑做出的技术决策，你希望最终能有一个好结果，来证明它是对的，但是决定结果的是过程，而过程则需要团队中每个成员贡献出自己的力量，怎么把你一个人的决策映射到团队，借助团队的力量来实现它呢？这就需要技术管理者拥有文化构建的能力。</p><h2 id="文化构建能力-让梦想变成理想" tabindex="-1">文化构建能力：让梦想变成理想 <a class="header-anchor" href="#文化构建能力-让梦想变成理想" aria-label="Permalink to &quot;文化构建能力：让梦想变成理想&quot;">​</a></h2><p>文化构建能力，听上去非常玄，怎样去构造一个团队的文化呢？其实你可以考虑，公司为什么要构建“使命、愿景、价值观”？这三个是企业文化中最重要的要素。但你有没有想过为什么要做这三件事情呢？</p><p>其实，答案很简单，使命、愿景、价值观，其实就是构建公司的这群人最初的理想。让一群人，相信一个事情，一起努力达成，这其实就是文化。一个企业、一个部门的文化，就是让理想变成现实的保障。</p><p>构造团队文化，最初的起点是高管团队自己，你自己是使命必达还是以人为本，是纪律严明还是自由宽松。你是怎样的人，想要拥有一支什么样的队伍，相应的团队就会有什么样的文化。往下推演，你招聘怎样的中坚力量，你就会有怎样的文化构成。当然，当团队达到一定规模之后，团队形成的文化也就会影响新的人融入到你的团队当中。因此定义好你部门的使命、愿景、价值观并营造合适的氛围，是管理者跨越到管理几百个人的关键点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这就是今天我要分享的内容，最后我们一起来回顾一下吧！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/04/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/04/3.png" alt=""></a></p><p>每个技术领导者从 0 到 10 再到上百上千都需要跨越很多个门槛，从原来做技术到做技术管理，需要具备几项关键能力。</p><ul><li><p>体系搭建能力，从遵守规则到建立规则。</p></li><li><p>技术实力，从做技术到做技术决策，要学会从多个维度去考量做出最合适的技术决策，在这个过程中你会经历无知而无畏、有知而有畏、有知而无畏三个阶段，等你真正到达第三个阶段的时候，你也就成为了一名优秀的技术领导者。</p></li><li><p>文化构建能力，要能把一个人的梦想变成一群人的理想，统一整个部门甚至整个公司的目标，构建部门 / 公司自己独特的文化，让一群人奔着一个目标去。</p></li></ul><p>开头我们说了技术管理者要提升 5 项能力，这节课我们聊了其中 3 项能力，领导力和人员管理能力也非常重要，下节课我会继续和你探讨技术管理者如何管人这一问题。希望今天的分享能够帮到你，也欢迎你把这节课分享给需要的朋友。我们下节课再见！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/04/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/04/4.png" alt=""></a></p>',39)])])}const c=t(n,[["render",s]]);export{u as __pageData,c as default};
